  AND NOT EXISTS (
    SELECT 1 FROM competition_events e
    WHERE e.competition_id = c.id
      AND e.data->>'rod'       = (v.data::jsonb)->>'rod'
      AND e.data->>'data'      = (v.data::jsonb)->>'data'
      AND e.data->>'mandante'  = (v.data::jsonb)->>'mandante'
      AND e.data->>'visitante' = (v.data::jsonb)->>'visitante'
  );

COMMIT;

-- Conferencia: apos as 3 fatias, jogos deve ser 75
SELECT 'jogos no Controle: ' || count(*) AS resultado
FROM competition_events
WHERE competition_id = (SELECT id FROM competitions WHERE slug = 'paulistao-a1');